// Clave de los datos de la tienda: solo el rol de la aplicación puede usarla. Localiza y corrige el defecto de su política.
export const template = {
  AWSTemplateFormatVersion: "2010-09-09",
  Description: "Clave KMS con rotación automática y un alias",
  Parameters: {
    RolAplicacion: { Type: "String" },
  },
  Resources: {
    ClaveDatos: {
      Type: "AWS::KMS::Key",
      Properties: {
        Description: "Clave de los datos de la tienda",
        EnableKeyRotation: true,
        KeyPolicy: {
          Version: "2012-10-17",
          Statement: [
            {
              Sid: "HabilitarPoliticasIAM",
              Effect: "Allow",
              Principal: { AWS: { "Fn::Join": ["", ["arn:aws:iam::", { Ref: "AWS::AccountId" }, ":root"]] } },
              Action: "kms:*",
              Resource: "*",
            },
            {
              Sid: "UsuariosDeLaClave",
              Effect: "Allow",
              Principal: { AWS: { Ref: "RolAplicacion" } },
              Action: ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey*", "kms:DescribeKey"],
              Resource: "*",
            },
          ],
        },
      },
    },
    AliasDatos: {
      Type: "AWS::KMS::Alias",
      Properties: { AliasName: "alias/datos-tienda", TargetKeyId: { Ref: "ClaveDatos" } },
    },
  },
};

spec.code:
const sentencias = template.Resources.ClaveDatos.Properties.KeyPolicy.Statement;
const texto = (sentencia) => JSON.stringify(sentencia.Principal);
const lista = (valor) => (Array.isArray(valor) ? valor : [valor]);
const cuenta = sentencias.find((sentencia) => texto(sentencia).includes("AWS::AccountId") && texto(sentencia).includes(":root"));
assert.ok(cuenta, "Falta la sentencia del principal de cuenta (arn:aws:iam::<cuenta>:root)");
assert.strictEqual(cuenta.Effect, "Allow");
assert.deepStrictEqual(lista(cuenta.Action), ["kms:*"]);

const sentencias = template.Resources.ClaveDatos.Properties.KeyPolicy.Statement;
const texto = (sentencia) => JSON.stringify(sentencia.Principal);
const lista = (valor) => (Array.isArray(valor) ? valor : [valor]);
const usuarios = sentencias.find((sentencia) => texto(sentencia).includes("RolAplicacion"));
assert.ok(usuarios, "Falta la sentencia del rol de la aplicación");
assert.strictEqual(usuarios.Effect, "Allow");
assert.deepStrictEqual(lista(usuarios.Action), ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey*", "kms:DescribeKey"]);

const propiedades = template.Resources.ClaveDatos.Properties;
assert.strictEqual(propiedades.EnableKeyRotation, true);
assert.deepStrictEqual(template.Resources.AliasDatos.Properties.TargetKeyId, { Ref: "ClaveDatos" });
const orden = aws.cfn.dependencyOrder(template);
assert.ok(orden !== null, "La plantilla no tiene un orden de creación");
assert.ok(orden.indexOf("ClaveDatos") < orden.indexOf("AliasDatos"), "La clave debe crearse antes que el alias");

