const tipos = Object.values(template.Resources).map((recurso) => recurso.Type);
assert.ok(tipos.includes("AWS::KMS::Key"), "Falta un recurso AWS::KMS::Key");
assert.ok(tipos.includes("AWS::KMS::Alias"), "Falta un recurso AWS::KMS::Alias");
assert.ok(aws.cfn.dependencyOrder(template) !== null, "La plantilla tiene una dependencia circular");

const orden = aws.cfn.dependencyOrder(template);
assert.ok(orden !== null, "La plantilla no tiene un orden de creación");
assert.ok(orden.indexOf("ClaveDatos") < orden.indexOf("AliasDatos"), "ClaveDatos debe crearse antes que AliasDatos");

const sentencias = template.Resources.ClaveDatos.Properties.KeyPolicy.Statement;
const texto = (sentencia) => JSON.stringify(sentencia.Principal);
const lista = (valor) => (Array.isArray(valor) ? valor : [valor]);
const cuenta = sentencias.find((sentencia) => texto(sentencia).includes("AWS::AccountId") && texto(sentencia).includes(":root"));
assert.ok(cuenta, "Falta la sentencia del principal de cuenta (arn:aws:iam::<cuenta>:root)");
assert.strictEqual(cuenta.Effect, "Allow");
assert.deepStrictEqual(lista(cuenta.Action), ["kms:*"]);

const sentencias = template.Resources.ClaveDatos.Properties.KeyPolicy.Statement;
const texto = (sentencia) => JSON.stringify(sentencia.Principal);
const lista = (valor) => (Array.isArray(valor) ? valor : [valor]);
const admin = sentencias.find((sentencia) => texto(sentencia).includes("RolAdministrador"));
const usuario = sentencias.find((sentencia) => texto(sentencia).includes("RolAplicacion"));
assert.ok(admin, "Falta la sentencia de los administradores de la clave");
assert.ok(usuario, "Falta la sentencia de los usuarios de la clave");
const accionesAdmin = lista(admin.Action);
const accionesUsuario = lista(usuario.Action);
assert.strictEqual(admin.Effect, "Allow");
assert.strictEqual(usuario.Effect, "Allow");
for (const accion of ["kms:*", "kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey*", "kms:ReEncrypt*"]) {
  assert.ok(!accionesAdmin.includes(accion), "Los administradores no deben poder usar la clave: " + accion);
