  assert.ok(!accionesUsuario.includes(accion), "Los usuarios no deben poder administrar la clave: " + accion);
}

assert.strictEqual(template.AWSTemplateFormatVersion, "2010-09-09");
assert.deepStrictEqual(Object.keys(template.Parameters).sort(), ["RolAdministrador", "RolAplicacion"]);
