// Clave de los informes: simétrica, rotación automática personalizada y acceso solo del rol de informes.
export const template = {
  AWSTemplateFormatVersion: "2010-09-09",
  Description: "Clave KMS de los informes con rotación automática cada 180 días",
  Parameters: {
    RolAdministrador: { Type: "String" },
    RolInformes: { Type: "String" },
  },
  Resources: {
    ClaveInformes: {
      Type: "AWS::KMS::Key",
      Properties: {
        Description: "Clave de los informes",
        KeySpec: "SYMMETRIC_DEFAULT",
        KeyUsage: "ENCRYPT_DECRYPT",
        EnableKeyRotation: true,
        RotationPeriodInDays: 180,
        KeyPolicy: {
          Version: "2012-10-17",
          Statement: [
            {
              Sid: "HabilitarPoliticasIAM",
              Effect: "Allow",
              Principal: { AWS: { "Fn::Join": ["", ["arn:aws:iam::", { Ref: "AWS::AccountId" }, ":root"]] } },
              Action: "kms:*",
              Resource: "*",
            },
            {
              Sid: "AdministradoresDeLaClave",
              Effect: "Allow",
              Principal: { AWS: { Ref: "RolAdministrador" } },
              Action: ["kms:Create*", "kms:Describe*", "kms:Enable*", "kms:List*", "kms:Put*", "kms:Update*", "kms:Revoke*", "kms:Disable*", "kms:Get*", "kms:ScheduleKeyDeletion", "kms:CancelKeyDeletion"],
              Resource: "*",
            },
            {
              Sid: "UsuariosDeLaClave",
              Effect: "Allow",
              Principal: { AWS: { Ref: "RolInformes" } },
              Action: ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey*", "kms:DescribeKey"],
              Resource: "*",
            },
          ],
        },
      },
    },
    AliasInformes: {
      Type: "AWS::KMS::Alias",
      Properties: { AliasName: "alias/informes", TargetKeyId: { Ref: "ClaveInformes" } },
    },
  },
  Outputs: { ArnClaveInformes: { Value: { "Fn::GetAtt": ["ClaveInformes", "Arn"] } } },
};

spec.code:
const tipos = Object.values(template.Resources).map((recurso) => recurso.Type);
assert.ok(tipos.includes("AWS::KMS::Key"), "Falta un recurso AWS::KMS::Key");
assert.ok(tipos.includes("AWS::KMS::Alias"), "Falta un recurso AWS::KMS::Alias");
const orden = aws.cfn.dependencyOrder(template);
assert.ok(orden !== null, "La plantilla no tiene un orden de creación");
assert.ok(orden.indexOf("ClaveInformes") < orden.indexOf("AliasInformes"), "La clave debe crearse antes que el alias");

const propiedades = template.Resources.ClaveInformes.Properties;
assert.strictEqual(propiedades.KeySpec, "SYMMETRIC_DEFAULT", "La rotación automática solo admite claves simétricas de cifrado");
assert.strictEqual(propiedades.KeyUsage, "ENCRYPT_DECRYPT");
assert.strictEqual(propiedades.EnableKeyRotation, true);

const sentencias = template.Resources.ClaveInformes.Properties.KeyPolicy.Statement;
const texto = (sentencia) => JSON.stringify(sentencia.Principal);
const lista = (valor) => (Array.isArray(valor) ? valor : [valor]);
const cuenta = sentencias.find((sentencia) => texto(sentencia).includes("AWS::AccountId") && texto(sentencia).includes(":root"));
assert.ok(cuenta, "Falta la sentencia del principal de cuenta (arn:aws:iam::<cuenta>:root)");
assert.strictEqual(cuenta.Effect, "Allow");
assert.deepStrictEqual(lista(cuenta.Action), ["kms:*"]);

const sentencias = template.Resources.ClaveInformes.Properties.KeyPolicy.Statement;
const texto = (sentencia) => JSON.stringify(sentencia.Principal);
const lista = (valor) => (Array.isArray(valor) ? valor : [valor]);
const usuario = sentencias.find((sentencia) => texto(sentencia).includes("RolInformes"));
assert.ok(usuario, "Falta la sentencia del rol de informes");
assert.ok(!texto(usuario).includes("*"), "El principal de los usuarios no puede ser un comodín");
const acciones = lista(usuario.Action);
for (const accion of ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey*"]) {
  assert.ok(acciones.includes(accion), "Debe poder usar la clave: " + accion);
}
for (const accion of ["kms:*", "kms:Put*", "kms:Create*", "kms:Enable*", "kms:Disable*", "kms:ScheduleKeyDeletion"]) {
  assert.ok(!acciones.includes(accion), "No debe administrar la clave: " + accion);
}
for (const sentencia of sentencias) {
  if (texto(sentencia).includes("RolAdministrador")) {
    for (const accion of ["kms:*", "kms:Encrypt", "kms:Decrypt"]) {
      assert.ok(!lista(sentencia.Action).includes(accion), "Los administradores no deben poder usar la clave: " + accion);
    }
  }
}

assert.strictEqual(template.AWSTemplateFormatVersion, "2010-09-09");
assert.deepStrictEqual(Object.keys(template.Parameters).sort(), ["RolAdministrador", "RolInformes"]);
assert.strictEqual(template.Resources.AliasInformes.Properties.AliasName, "alias/informes");
